Scheme kc__4 := Elimination for Corelib.Init.Logic.ex Sort Prop.

Lemma rs_eof_facts : forall c g, pcore_ok c ->
  pcore_ok (rs_eof_c c) /\ ec_ok (rs_eof_E c)
  /\ ((http_fail (rs_eof_E c) /\ rs_eof_c c = c) \/ (rs_eof_E c = EC_clear /\ pc_state (rs_eof_c c) = 11))
  /\ (pc_state c = 0 -> rs_eof_g c g = true).
