(* [comment removed for export] *)
(* [comment removed for export] *)
Definition rs_eof_W (lo : Z) (sp : word) (P E ff : Z) : list (Z * Z) :=
  [(lo, bv_unsigned sp + -104); (P, P + 80); (E, E + 24); (AG_HTTP_CAT, AG_HTTP_CAT + 64);
   (Z.shiftr ff 3 + 2147450880 + 4, Z.shiftr ff 3 + 2147450880 + 7)]%Z.

Definition rs_eof_post (ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v : word) (F : bvmap 5 word) (fc : bv 32) (LF : list fframe)
    (lo shi E P tot ff fp : Z) (c : pcore) (pad7 pad2 : list byte) (g : bool) (m : mem) : machine_state -> Prop :=
  fun ms' => exists m',
       munch (rs_eof_W lo sp P E ff) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ rw_cells bsegs m' P (ParserCoreCells (rs_eof_c c) pad7 pad2)
    /\ rw_cells bsegs m' E (ErrCodeCells (rs_eof_E c))
    /\ AHttpCat m' (rs_eof_g c g) /\ AXStatics2 m' /\ ACONST m' /\ stack0 m' lo shi
    /\ rs_retd_post H ra sp gp tp s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v F fc LF lo shi ff fp tot m' ms'.

Lemma rs_eof : forall rax sp gp tp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6
    (s0v s1v s2v s3v s4v s5v s6v s7v s8v s9v s10v s11v ra : word)
    (F : bvmap 5 word) fc (m0 m : mem) (LF : list fframe) (lo shi spa ff fp E bs fb P tot : Z) (c : pcore) (pad7 pad2 : list byte) (g : bool)
    (hw : word) (tmp gap optc ectc : list cell) (j56 j120 : list byte),
  as_RFS H LF m0 ->
  rs_frame m sp spa ff E bs P fb (C8 (wz (Z.shiftr (E + 16) 3 + 2147450880))) tmp gap ->
  rw_cells bsegs m (bv_unsigned sp + -104) (rs_sv s11v s10v s9v s8v s7v s6v s5v s4v s3v s2v s1v s0v ra) ->
  rs_fake m ff fp hw optc j56 ectc j120 0 248 -> as_RFS H ((2, ff, fp) :: LF) m -> fresh_frame H LF 2 ff fp ->
  rw_cells bsegs m P (ParserCoreCells c pad7 pad2) -> pcore_ok c ->
